def complement(intervals, start, end):
    """Return free intervals within [start, end] given blocked intervals (sorted, non‑overlapping)."""
    free = []
    cur = start
    for b_start, b_end in intervals:
        if cur < b_start:
            free.append((cur, b_start))
        cur = max(cur, b_end)
    if cur < end:
        free.append((cur, end))
    return free

def intersect(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s1, e1 = a[i]
        s2, e2 = b[j]
        s = max(s1, s2)
        e = min(e1, e2)
        if s < e:
            res.append((s, e))
        if e1 < e2:
            i += 1
        else:
            j += 1
    return res

