import sys
from datetime import datetime, timedelta

# ----- Data definition -----
DAYS = ["Monday", "Tuesday", "Wednesday"]
WORK_START = 9 * 60   # minutes since midnight
WORK_END = 17 * 60    # minutes since midnight
MEETING_DURATION = 30  # minutes

# Busy intervals for each participant (day -> list of (start, end) in minutes)
busy = {
    "Nancy": {
        "Monday":    [("10:00", "10:30"), ("11:30", "12:30"), ("13:30", "14:00"),
                     ("14:30", "15:30"), ("16:00", "17:00")],
        "Tuesday":   [("09:30", "10:30"), ("11:00", "11:30"), ("12:00", "12:30"),
                     ("13:00", "13:30"), ("15:30", "16:00")],
        "Wednesday": [("10:00", "11:30"), ("13:30", "16:00")]
    },
    "Jose": {
        "Monday":    [("09:00", "17:00")],
        "Tuesday":   [("09:00", "17:00")],
        "Wednesday": [("09:00", "09:30"), ("10:00", "12:30"),
                      ("13:30", "14:30"), ("15:00", "17:00")]
    }
}

def to_minutes(t: str) -> int:
    """Convert HH:MM string to minutes since midnight."""
    h, m = map(int, t.split(":"))
    return h * 60 + m

def complement(busy_intervals):
    """Given sorted busy intervals within work window, return free intervals."""
    free = []
    cur = WORK_START
    for s, e in busy_intervals:
        if s > cur:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < WORK_END:
        free.append((cur, WORK_END))
    return free

def intersect_intervals(list1, list2):
    """Intersect two lists of intervals (both sorted, non‑overlapping)."""
    i, j = 0, 0
    result = []
    while i < len(list1) and j < len(list2):
        a_start, a_end = list1[i]
        b_start, b_end = list2[j]
        start = max(a_start, b_start)
        end = min(a_end, b_end)
        if start < end:
            result.append((start, end))
        if a_end <= b_end:
            i += 1
        else:
            j += 1
    return result

def find_earliest_slot():
    for day in DAYS:
        # Build free intervals for each participant on this day
        common_free = [(WORK_START, WORK_END)]
        for person in busy:
            intervals = [(to_minutes(s), to_minutes(e)) for s, e in busy[person].get(day, [])]
            intervals.sort()
            free = complement(intervals)
            common_free = intersect_intervals(common_free, free)
            if not common_free:
                break  # no common free time on this day
        # Look for a slot long enough
        for start, end in common_free:
            if end - start >= MEETING_DURATION:
                meeting_start = start
                meeting_end = start + MEETING_DURATION
                fmt = lambda m: f"{m//60:02d}:{m%60:02d}"
                return [day, fmt(meeting_start), fmt(meeting_end)]
    return None

if __name__ == "__main__":
    answer = find_earliest_slot()
    if answer:
        print(answer)
    else:
        print("No feasible meeting time found", file=sys.stderr)

import itertools

# Helper functions
def hhmm_to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def min_to_hhmm(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

def subtract_intervals(whole, parts):
    """Subtract a list of non-overlapping intervals `parts` from `whole` interval.
    Returns a list of remaining intervals."""
    result = []
    start, end = whole
    cur = start
    for p_start, p_end in sorted(parts):
        if p_start > cur:
            result.append((cur, min(p_start, end)))
        cur = max(cur, p_end)
        if cur >= end:
            break
    if cur < end:
        result.append((cur, end))
    return result

def intersect_two(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        a_start, a_end = a[i]
        b_start, b_end = b[j]
        start = max(a_start, b_start)
        end = min(a_end, b_end)
        if start < end:
            res.append((start, end))
        if a_end <= b_end:
            i += 1
        else:
            j += 1
    return res

def intersect_all(lists):
    """Intersect a sequence of interval lists."""
    if not lists:
        return []
    res = lists[0]
    for lst in lists[1:]:
        res = intersect_two(res, lst)
        if not res:
            break
    return res

# Problem data
participants = {
    "Cheryl": {
        "Monday":    [("09:00", "09:30"), ("11:30", "13:00"), ("15:30", "16:00")],
        "Tuesday":   [("15:00", "15:30")],
        "Wednesday": []  # no busy slots but Cheryl cannot meet Wed (handled later)
    },
    "Kyle": {
        "Monday":    [("09:00", "17:00")],
        "Tuesday":   [("09:30", "17:00")],
        "Wednesday": [("09:00", "09:30"), ("10:00", "13:00"),
                      ("13:30", "14:00"), ("14:30", "17:00")]
    }
}

work_start = hhmm_to_min("09:00")
work_end   = hhmm_to_min("17:00")
meeting_duration = 30  # minutes

allowed_days = ["Monday", "Tuesday", "Wednesday"]
# Cheryl cannot meet on Wednesday
allowed_days = [d for d in allowed_days if d != "Wednesday"]

# Compute free intervals for each participant per day
free = {person: {} for person in participants}
for person, schedule in participants.items():
    for day in allowed_days:
        busy = [(hhmm_to_min(s), hhmm_to_min(e)) for s, e in schedule.get(day, [])]
        free_intervals = subtract_intervals((work_start, work_end), busy)
        free[person][day] = free_intervals

# Find a feasible slot
solution = None
for day in allowed_days:
    common = intersect_all([free[p][day] for p in participants])
    for start, end in common:
        if end - start >= meeting_duration:
            meeting_start = start
            meeting_end = start + meeting_duration
            solution = [day, min_to_hhmm(meeting_start), min_to_hhmm(meeting_end)]
            break
    if solution:
        break

print(solution)

import itertools

# Helper functions
def time_to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def min_to_time(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

def complement_intervals(intervals, start, end):
    """Return gaps between start..end that are not covered by intervals (sorted, non‑overlapping)."""
    if not intervals:
        return [(start, end)]
    intervals = sorted(intervals)
    free = []
    cur = start
    for a, b in intervals:
        if a > cur:
            free.append((cur, a))
        cur = max(cur, b)
    if cur < end:
        free.append((cur, end))
    return free

def intersect_intervals(list1, list2):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    result = []
    while i < len(list1) and j < len(list2):
        a1, b1 = list1[i]
        a2, b2 = list2[j]
        start = max(a1, a2)
        end = min(b1, b2)
        if start < end:
            result.append((start, end))
        if b1 < b2:
            i += 1
        else:
            j += 1
    return result

