import sys

# Define work days and hours (in minutes from midnight)
DAYS = ["Monday", "Tuesday", "Wednesday"]
WORK_START = 9 * 60
WORK_END = 17 * 60
MEETING_DURATION = 30  # minutes

# Busy intervals per person per day (start inclusive, end exclusive) in minutes
busy = {
    "Tyler": {
        "Monday": [],
        "Tuesday": [(9*60, 9*60+30), (14*60+30, 15*60)],
        "Wednesday": [(10*60+30, 11*60), (12*60+30, 13*60),
                      (13*60+30, 14*60), (16*60+30, 17*60)],
    },
    "Ruth": {
        "Monday": [(9*60, 10*60), (10*60+30, 12*60),
                   (12*60+30, 14*60+30), (15*60, 16*60),
                   (16*60+30, 17*60)],
        "Tuesday": [(9*60, 17*60)],
        "Wednesday": [(9*60, 17*60)],
    },
}

def overlaps(slot_start, slot_end, intervals):
    """Return True if [slot_start, slot_end) overlaps any interval."""
    for s, e in intervals:
        if slot_start < e and s < slot_end:
            return True
    return False

def minutes_to_str(m):
    h = m // 60
    mi = m % 60
    return f"{h:02d}:{mi:02d}"

candidates = []

for day in DAYS:
    # generate possible start times within work hours
    latest_start = WORK_END - MEETING_DURATION
    for start in range(WORK_START, latest_start + 1):
        end = start + MEETING_DURATION
        # check both participants
        if overlaps(start, end, busy["Tyler"][day]):
            continue
        if overlaps(start, end, busy["Ruth"][day]):
            continue
        candidates.append((day, start, end))

# Preference: avoid Monday before 16:00
def preference_key(item):
    day, start, _ = item
    bad = 1 if (day == "Monday" and start < 16*60) else 0
    return (bad, start)

candidates.sort(key=preference_key)

if not candidates:
    sys.exit("No feasible meeting time found")

chosen_day, chosen_start, chosen_end = candidates[0]
result = [chosen_day, minutes_to_str(chosen_start), minutes_to_str(chosen_end)]
print(result)

from datetime import datetime, timedelta

# Helper functions
def to_minutes(t: str) -> int:
    """Convert 'HH:MM' to minutes since midnight."""
    h, m = map(int, t.split(':'))
    return h * 60 + m

def to_time_str(m: int) -> str:
    """Convert minutes since midnight to zero-padded 'HH:MM'."""
    h = m // 60
    m = m % 60
    return f"{h:02d}:{m:02d}"

def complement(intervals, work_start, work_end):
    """Return free intervals within work window given busy intervals (sorted, non‑overlapping)."""
    free = []
    prev_end = work_start
    for s, e in intervals:
        if s > prev_end:
            free.append((prev_end, s))
        prev_end = max(prev_end, e)
    if prev_end < work_end:
        free.append((prev_end, work_end))
    return free

def intersect_intervals(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    result = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            result.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return result

