for person in blocked:
    for day in blocked[person]:
        blocked[person][day] = [(time_to_min(s), time_to_min(e)) for s, e in blocked[person][day]]

# Preferences expressed as additional blocked intervals
# Margaret does not want Monday at all, and does not want Tuesday before 14:30
if "Margaret" not in blocked:
    blocked["Margaret"] = {}
# Block entire Monday
blocked["Margaret"].setdefault("Monday", []).append((WORK_START, WORK_END))
# Block Tuesday before 14:30
blocked["Margaret"].setdefault("Tuesday", []).append((WORK_START, time_to_min("14:30")))

def interval_free(day: str, start: int, end: int) -> bool:
    """Check if the interval [start, end) is free for all participants on given day."""
    for person, days in blocked.items():
        for s, e in days.get(day, []):
            # Overlap if not (end <= s or start >= e)
            if not (end <= s or start >= e):
                return False
    return True

