    # iterate start times at minute granularity
    start = WORK_START
    while start + MEETING_DURATION <= WORK_END:
        end = start + MEETING_DURATION
        if interval_free(day, start, end):
            solution = [day, min_to_time(start), min_to_time(end)]
            break
        start += 1
    if solution:
        break

print(solution)

import sys

# Helper functions
def to_min(t):
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m):
    h = m // 60
    mi = m % 60
    return f"{h:02d}:{mi:02d}"

def complement(busy, work_start, work_end):
    """Return free intervals inside [work_start, work_end] given sorted busy intervals."""
    free = []
    cur = work_start
    for s, e in busy:
