    free = []
    start, end = base
    i = start
    for b_start, b_end in sorted(busy):
        if b_end <= i:
            continue
        if b_start <= i < b_end:
            i = b_end
        elif i < b_start:
            free.append((i, min(b_start, end)))
            i = b_end
        if i >= end:
            break
    if i < end:
        free.append((i, end))
    return free

