def day_busy(day):
    intervals = []
    for start, end in natalie_busy.get(day, []):
        s = max(to_minutes(start), work_start)
        e = min(to_minutes(end), work_end)
        if s < e:
            intervals.append((s, e))
    for start, end in william_busy.get(day, []):
        s = max(to_minutes(start), work_start)
        e = min(to_minutes(end), work_end)
        if s < e:
            intervals.append((s, e))
    return merge_intervals(intervals)

def find_meeting():
    for day in days:
        busy = day_busy(day)
        cursor = work_start
        for b_start, b_end in busy:
            if b_start - cursor >= meeting_len:
                return day, cursor, cursor + meeting_len
            cursor = max(cursor, b_end)
        if work_end - cursor >= meeting_len:
            return day, cursor, cursor + meeting_len
    return None

