# Convert hour.decimal to minutes (e.g., 9.5 -> 570)
def to_minutes(intervals):
    res = []
    for s, e in intervals:
        start = int(s * 60)
        end = int(e * 60)
        res.append((start, end))
    return res

for person in busy:
    for day in busy[person]:
        busy[person][day] = to_minutes(busy[person][day])

# Preference: on Wednesday Ruth does not want start > 13:30
def preference_ok(day, start):
    if day == "Wednesday" and start > 13 * 60 + 30:
        return False
    return True

# ------------------- Helper functions -------------------
def subtract_interval(free, busy_interval):
    """Subtract a single busy interval from a list of free intervals."""
    result = []
    b_start, b_end = busy_interval
    for f_start, f_end in free:
        if b_end <= f_start or b_start >= f_end:
            # no overlap
            result.append((f_start, f_end))
        else:
            # overlap exists, possibly split
            if b_start > f_start:
                result.append((f_start, b_start))
            if b_end < f_end:
                result.append((b_end, f_end))
    return result

def compute_free(person, day):
    """Return list of free intervals for person on given day within work hours."""
    free = [(work_start, work_end)]
    for b in busy[person].get(day, []):
        free = subtract_interval(free, b)
    return free

def intersect_intervals(list1, list2):
    """Intersect two lists of intervals (both sorted, non‑overlapping)."""
    i, j = 0, 0
    result = []
    while i < len(list1) and j < len(list2):
        a_start, a_end = list1[i]
        b_start, b_end = list2[j]
        start = max(a_start, b_start)
        end = min(a_end, b_end)
        if start < end:
            result.append((start, end))
        if a_end <= b_end:
            i += 1
        else:
            j += 1
    return result

def minutes_to_str(m):
    h = m // 60
    mi = m % 60
    return f"{h:02d}:{mi:02d}"

# ------------------- Search -------------------
for day in days:
    # start with free intervals of the first participant
    common_free = compute_free("Nicole", day)
    # intersect with each other participant
    for person in ["Ruth"]:
        common_free = intersect_intervals(common_free, compute_free(person, day))
        if not common_free:
