import sys

def to_min(time_str):
    """Convert 'HH:MM' to minutes since midnight."""
    h, m = map(int, time_str.split(':'))
    return h * 60 + m

def to_str(minutes):
    """Convert minutes since midnight to zero‑padded 'HH:MM'."""
    h = minutes // 60
    m = minutes % 60
    return f"{h:02d}:{m:02d}"

def complement(interval, busy):
    """Return free intervals within `interval` after removing `busy` intervals."""
    start, end = interval
    free = []
    cur = start
    for b_start, b_end in sorted(busy):
        if b_start > cur:
            free.append((cur, min(b_start, end)))
        cur = max(cur, b_end)
        if cur >= end:
            break
    if cur < end:
        free.append((cur, end))
    return free

def intersect_intervals(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    result = []
    while i < len(a) and j < len(b):
        a_start, a_end = a[i]
        b_start, b_end = b[j]
        s = max(a_start, b_start)
        e = min(a_end, b_end)
        if s < e:
            result.append((s, e))
        if a_end <= b_end:
            i += 1
        else:
            j += 1
    return result

def find_meeting(free_lists, duration):
    """Find earliest slot of at least `duration` minutes common to all free lists."""
    common = free_lists[0]
    for fl in free_lists[1:]:
        common = intersect_intervals(common, fl)
        if not common:
            return None
    for start, end in common:
        if end - start >= duration:
            return start, start + duration
    return None

def main():
    # Problem data (hard‑coded for the given instance)
    day = "Monday"
    meeting_duration = 30  # minutes

    # Work window for all participants (9:00‑17:00)
    work_start = to_min("09:00")
    work_end = to_min("17:00")

    # Participant definitions
    participants = {
        "Juan": {
            "busy": [("09:00", "10:30"), ("15:30", "16:00")],
            "latest_end": to_min("16:00")  # cannot meet after 16:00
        },
        "Marilyn": {
            "busy": [("11:00", "11:30"), ("12:30", "13:00")],
            "latest_end": work_end
        },
        "Ronald": {
            "busy": [("09:00", "10:30"), ("12:00", "12:30"),
                     ("13:00", "13:30"), ("14:00", "16:30")],
            "latest_end": work_end
        },
    }

    free_lists = []
    for p, info in participants.items():
        # Convert busy intervals to minutes
        busy_min = [(to_min(s), to_min(e)) for s, e in info["busy"]]
        # Effective work window respecting latest_end constraint
        end_limit = min(work_end, info["latest_end"])
        work_interval = (work_start, end_limit)
        # Compute free intervals
        free = complement(work_interval, busy_min)
        free_lists.append(free)

    slot = find_meeting(free_lists, meeting_duration)
    if slot is None:
        print("No feasible meeting time found", file=sys.stderr)
        sys.exit(1)

    start_str = to_str(slot[0])
    end_str = to_str(slot[1])
    result = [day, start_str, end_str]
    print(result)

if __name__ == "__main__":
    main()

import datetime

# ----- Data ---------------------------------------------------------

# Work window (inclusive start, exclusive end)
WORK_START = datetime.time(9, 0)
WORK_END   = datetime.time(17, 0)

MEETING_DURATION = datetime.timedelta(hours=1)

# Blocked intervals per participant per day
# Each interval is a pair (start_time, end_time) as datetime.time
blocked = {
    'Martha': {
        'Monday':    [(datetime.time(16, 0), datetime.time(17, 0))],
        'Tuesday':   [(datetime.time(15, 0), datetime.time(15, 30))],
        'Wednesday': [(datetime.time(10, 0), datetime.time(11, 0)),
                      (datetime.time(14, 0), datetime.time(14, 30))],
    },
    'Beverly': {
        'Monday':    [(datetime.time(9, 0),  datetime.time(13, 30)),
                      (datetime.time(14, 0), datetime.time(17, 0))],
        'Tuesday':   [(datetime.time(9, 0),  datetime.time(17, 0))],
        'Wednesday': [(datetime.time(9, 30), datetime.time(15, 30)),
                      (datetime.time(16, 30),datetime.time(17, 0))],
    },
}

DAYS = ['Monday', 'Tuesday', 'Wednesday']

# ----- Helper functions ----------------------------------------------

def time_range(start: datetime.time, end: datetime.time):
    """Yield datetime.time values from start (inclusive) to end (exclusive) minute by minute."""
    dt = datetime.datetime.combine(datetime.date.min, start)
    end_dt = datetime.datetime.combine(datetime.date.min, end)
    while dt < end_dt:
        yield dt.time()
        dt += datetime.timedelta(minutes=1)

def overlaps(interval_start, interval_end, blocked_intervals):
    """Check if [interval_start, interval_end) overlaps any blocked interval."""
    for b_start, b_end in blocked_intervals:
        # Overlap exists if start < b_end and b_start < end
        if (interval_start < b_end) and (b_start < interval_end):
            return True
    return False

# ----- Search ---------------------------------------------------------

def find_meeting():
    for day in DAYS:
        # Generate possible start times aligned to the minute
        for start in time_range(WORK_START, (datetime.datetime.combine(
                datetime.date.min, WORK_END) - MEETING_DURATION).time()):
            end_dt = (datetime.datetime.combine(datetime.date.min, start)
                      + MEETING_DURATION)
            end = end_dt.time()
            # Ensure end is not beyond work window
            if end > WORK_END:
                continue
            conflict = False
            for person, schedule in blocked.items():
                intervals = schedule.get(day, [])
                if overlaps(start, end, intervals):
                    conflict = True
                    break
            if not conflict:
                return day, start.strftime("%H:%M"), end.strftime("%H:%M")
    return None

# ----- Output ---------------------------------------------------------

result = find_meeting()
if result:
    print([result[0], result[1], result[2]])

import sys
from datetime import datetime, timedelta

# Helper to convert "H:MM" or "HH:MM" to minutes since midnight
def to_min(t):
    h, m = map(int, t.split(':'))
    return h * 60 + m

# Helper to convert minutes since midnight to zero‑padded "HH:MM"
def to_str(m):
    h = m // 60
    mi = m % 60
    return f"{h:02d}:{mi:02d}"

# Busy intervals per participant per day (inclusive start, exclusive end)
busy = {
    "Stephanie": {
        "Monday":    [("9:30", "10:00"), ("10:30", "11:00"), ("11:30", "12:00"), ("14:00", "14:30")],
        "Tuesday":   [("12:00", "13:00")],
        "Wednesday": [("9:00", "10:00"), ("13:00", "14:00")]
    },
    "Betty": {
        "Monday":    [("9:00", "10:00"), ("11:00", "11:30"), ("14:30", "15:00"), ("15:30", "16:00")],
        "Tuesday":   [("9:00", "9:30"), ("11:30", "12:00"), ("12:30", "14:30"), ("15:30", "16:00")],
        "Wednesday": [("10:00", "11:30"), ("12:00", "14:00"), ("14:30", "17:00")]
    }
}

# Convert all intervals to minute pairs
for person in busy:
    for day in busy[person]:
        busy[person][day] = [(to_min(s), to_min(e)) for s, e in busy[person][day]]

DAYS = ["Monday", "Tuesday", "Wednesday"]
MEETING_DURATION = 60          # minutes
WORK_START = to_min("9:00")
WORK_END   = to_min("17:00")

def fits(day, start):
    """Check whether a meeting starting at `start` on `day` satisfies all constraints."""
    end = start + MEETING_DURATION
    # Work‑hour window
    if start < WORK_START or end > WORK_END:
        return False
    # Betty’s Tuesday after‑12:30 restriction
    if day == "Tuesday" and end > to_min("12:30"):
        return False
    # No overlap with any busy interval of either participant
    for person in busy:
        for b_start, b_end in busy[person].get(day, []):
            # intervals overlap iff start < b_end and b_start < end
            if start < b_end and b_start < end:
                return False
    return True

def find_slot():
    """Return the first feasible slot respecting the preference order."""
    # Preference order: Tuesday, Wednesday, Monday
    preferred_order = ["Tuesday", "Wednesday", "Monday"]
    for day in preferred_order:
        # iterate start times minute by minute within work window
        for start in range(WORK_START, WORK_END - MEETING_DURATION + 1):
            if fits(day, start):
                return day, start, start + MEETING_DURATION
    return None  # should never happen given problem guarantees

result = find_slot()
if result is None:
    sys.exit("No feasible meeting time found")
day, start, end = result
output = [day, to_str(start), to_str(end)]
print(output)
